head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — listSync 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let vCurDate = $c.date.formatDateTime(new Date());
        ibx_SDate.setValue( vCurDate );
        await scwin.listSync() ;    // 조회

        // 컴포넌트 객체 전달
        $c.date.checkCalendarFormat("ibx_SDate", "yyyyMMdd");

        // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행한다.
        $c.win.setEnterKeyEvent(tbl_search, scwin.btn_search_onclick);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.onpageload" });
    }
}

