/**
 * @method
 * @name img_coSearch_onclick
 * @description 회사선택호출
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_coSearch_onclick = async function (e) {
    try {
        // scwin.fn_GetPar = scwin.getParIsur();
        // scwin.fn_SetPar = scwin.setParIsur();
        const res = await $c.lc.popFindCorpChrg(scwin.fr_SecuGrpId);
        ibx_isur_cd.setValue(res.isurCd)
        ibx_com_nm.setValue(res.comAbbrv)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.img_coSearch_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name btn_search_onclick
 * @description btn_search click event
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = function (e) {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀다운로드
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        const tabIndex = tab_main.getSelectedTabIndex();

        switch (tabIndex) {

            case 0: // ELW
                if (grd_List1.getRowCount() <= 0) {
                    $c.win.alert("조회된 데이터가 없습니다.");
                    return;
                }
                $c.data.downloadGridViewExcel(grd_List1, {fileName: "인증및 자격관리", sheetName: "ELW"});
                break;

            case 1: // ETN
                if (grd_List2.getRowCount() <= 0) {
                    $c.win.alert("조회된 데이터가 없습니다.");
                    return;
                }
                $c.data.downloadGridViewExcel(grd_List2, {fileName: "기술성장기업", sheetName: "ETN"});
                break;

            case 2: // ETF
                if (grd_List3.getRowCount() <= 0) {
                $c.win.alert("조회된 데이터가 없습니다.");
                return;
                }
                $c.data.downloadGridViewExcel(grd_List3, {fileName: "상장형 수익증권 회사별 업무담당자_ETF", sheetName: "ETF"});
                break;

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name tab_main_ontabclick
 * @description tab_main_ontabclick click event
 * @returns {void}
 * @hidden N
 */
scwin.tab_main_ontabclick = function (tabId, index) {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.tab_main_ontabclick" });
    }
};

/**
 * @method
 * @Event
 * @name btn_New_onclick
 * @description btn_New_onclick click event
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick= function (e) {
    try {
        scwin.openDetail("C");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.btn_New_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name grd_List1_oncelldblclick
 * @description grd_List1_oncelldblclick click event
 * @returns {void}
 * @hidden N
 */
scwin.grd_List1_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if(columnId === "isurNm") {
            scwin.openDetail("U");
        } else if(columnId === "saveFileNm") {
            scwin.fileDown(rowIndex);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.grd_List1_oncelldblclick" });
    }
}

/**
 * @method
 * @Event
 * @name grd_list3_oneditdblclick
 * @description grd_list3_oneditdblclick click event
 * @returns {void}
 * @hidden N
 */
scwin.grd_list3_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.openDetail("U");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.grd_list3_oncelldblclick" });
    }
};

/**
 * @method
 * @Event
 * @name btn_close_ondblclick
 * @description grd_list3_onheaderdblclick click event
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_ondblclick = function (e) {

};

/**
 * @method
 * @Event
 * @name btn_new_onclick
 * @description 라이징스타 신규 버튼event
 * @returns {void}
 * @hidden N
 */
scwin.btn_new_onclick = async function (e) {
    try {
        await scwin.openDetail("C");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.btn_new_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description btn_Input 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Input_onclick = function (e) {
    try {
        scwin.risingStarRegPop();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.btn_Input_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @func
 * @name fn_list_sync
 * @description 조회함수
 * @returns {void}
 * @hidden N
 */
scwin.listSync = async function() {

    dma_searchReq.set("isurCd",ibx_isur_cd.getValue());
    dma_searchReq.set("listDd",ibx_SDate.getValue());

    const tabIndex =tab_main.getSelectedTabIndex()
    switch (tabIndex) {
        case 0:   // 인증및자격 탭
            btn_input.hide();
            btn_new.show();
            let sbmOptions1 = {
                id : "sbm_corpchrgList",
                action : "/api/listing/lstmgt/sect-authqual/select-list-authqual",
                method : "get",
                ref : "dma_searchReq",
                target : "dlt_authqualRes=body",
                gridview : "grd_List1|focus",
                isProcessMsg : true
            };
            const res = await $c.sbm.executeDynamic(sbmOptions1);

            if(res.responseJSON.success) {
                const rowCount = res.responseJSON.body.length;
            }

            break;

        case 1: // 기술성장기업4

            btn_input.hide();
            btn_new.hide();
            const sbmOptions2 = {
                id : "sbm_techgrwthcomList",
                action : "/api/listing/lstmgt/sect-authqual/select-list-techgrwthcom",
                method : "get",
                ref : "dma_searchReq",
                target : "dlt_techgrwthcomRes=body",
                gridview : "grd_List2|focus",
                isProcessMsg : true
            };

            $c.sbm.executeDynamic(sbmOptions2);

            break;

        case 2:  // 라이징스타

        btn_input.show();
        btn_new.show();
        const sbmOptions3 = {
            id : "sbm_hdnchampList",
            action : "/api/listing/lstmgt/sect-authqual/select-list-hdnchamp",
            method : "get",
            ref : "dma_searchReq",
            target : "dlt_hdnchampRes=body",
            gridview : "grd_List3|focus",
            isProcessMsg : true
        };

            $c.sbm.executeDynamic(sbmOptions3);

            break;
    }

}

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 부모 화면(팝업 호출원)으로 돌려줄 파라미터 배열을 만든다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name openDetail
 * @description 소속부 인증·자격 상세 팝업을 호출한다(flag 로 신규/상세를 구분).
 * @param {Boolean} flag 플래그
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(flag) {

    const tabIndex = tab_main.getSelectedTabIndex()

    if (tabIndex === 0) {

        const rowIndex = dlt_authqualRes.getRowPosition();

        const isurCd = dlt_authqualRes.getCellData(rowIndex, "isurCd");
        const isurNm = dlt_authqualRes.getCellData(rowIndex,"isurNm");
        const inputRnd = dlt_authqualRes.getCellData(rowIndex,"inputRnd");
        const acptNo = dlt_authqualRes.getCellData(rowIndex,"acptNo");

        let displayFlag = "";

        if(flag === "C") {
            displayFlag = "C"
        } else {
            displayFlag = "U"
        }

        const popupData = {
                "isurCd" : isurCd,                         
                "isurNm" : isurNm,                         
                "inputRnd" : inputRnd,     
                "acptNo"   :  acptNo,              
                "displayFlag" :displayFlag ,                              
        };

        const url = "/ui/lst/lstmgt/ULDSTF05961.xml";
        const popTitle = "인증및자격 관리";

        const opts = {
                id: "ULDSTF05961",
                popupName: popTitle,
                width: 900,
                height: 1150,
                frameModal: "top",
        };

        $c.win.openPopup(url, opts, popupData);

    } else if (tabIndex === 2 ){

        const rowIndex = dlt_hdnchampRes.getRowPosition();

        const isurCd = dlt_hdnchampRes.getCellData(rowIndex, "isurCd");
        const isurNm = dlt_hdnchampRes.getCellData(rowIndex,"isurNm");
        const inputRnd = dlt_hdnchampRes.getCellData(rowIndex,"inputRnd");

        let displayFlag = "";

        if(flag === "C") {
            displayFlag = "C"
        } else {
            displayFlag = "U"
        }

        const popupData = {
                "isurCd" : isurCd,                         
                "isurNm" : isurNm,                         
                "inputRnd" : inputRnd,     
                "displayFlag" :displayFlag                             
        };

        const url = "/ui/lst/lstmgt/ULDSTF05962.xml";
        const popTitle = "라이징스타 관리";
        const opts = {
                id: "ULDSTF05962",
                popupName: popTitle,
                width: 800,
                height: 450,
                frameModal: "top",
        };

        await $c.win.openPopup(url, opts, popupData);
        scwin.listSync();
    }

};

/**
 * @method
 * @name fileDown
 * @description 선택 행의 첨부파일을 다운로드한다.
 * @param {Number} rowIndex 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.fileDown = function(rowIndex) {

        const disclsDocNo = dlt_authqualRes.getCellData(rowIndex, "disclsDocNo");
        const attachSeq = dlt_authqualRes.getCellData(rowIndex, "attachSeq");
        const saveFileNm = dlt_authqualRes.getCellData(rowIndex, "saveFileNm");
        const gubunVal = "13";

        const url = "/api/listing/common/file/file-download";

        const param = {
                        gubun : gubunVal
                        ,fileId : disclsDocNo
                        ,attachSeq : attachSeq
                    };

        if(disclsDocNo !== "") { $c.data.downFile(url, saveFileNm, param) };
}

/**
 * @method
 * @name risingStarRegPop
 * @description 라이징스타 등록 팝업을 연다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.risingStarRegPop = async function(){

        const url = "/ui/lst/lstmgt/ULDSTF05963.xml";
        const popTitle = "라이징스타 등록";
        const opts = {
                id: "ULDSTF05963",
                popupName: popTitle,
                width: 1050,
                height: 750,
                frameModal: "top",
        };

        await $c.win.openPopup(url, opts, {});
        scwin.listSync();
}
